const allItems = [...moviesData, ...seriesData];
let favorites = JSON.parse(localStorage.getItem('cineMatchFavorites')) || [];
let watched = JSON.parse(localStorage.getItem('cineMatchWatched')) || [];

function saveToLocalStorage() {
    localStorage.setItem('cineMatchFavorites', JSON.stringify(favorites));
    localStorage.setItem('cineMatchWatched', JSON.stringify(watched));
}

function isFavorite(id) { return favorites.includes(id); }
function isWatched(id) { return watched.includes(id); }

// УБРАНА АНИМАЦИЯ ОБНОВЛЕНИЯ (просто сохраняем и перерисовываем)
function toggleFavorite(id) {
    if (isFavorite(id)) favorites = favorites.filter(favId => favId !== id);
    else favorites.push(id);
    saveToLocalStorage();
    renderCurrentView();
    if (currentTab === 'recommended') renderRecommended();
}

function toggleWatched(id) {
    if (isWatched(id)) watched = watched.filter(watchId => watchId !== id);
    else watched.push(id);
    saveToLocalStorage();
    renderCurrentView();
    if (currentTab === 'recommended') renderRecommended();
}

function getGenreDisplay(genreArray) {
    if (!genreArray) return "";
    const genreMap = {
        horror: "Ужасы", thriller: "Триллер", comedy: "Комедия",
        drama: "Драма", detective: "Детектив", crime: "Криминал",
        fantasy: "Фэнтези", adventure: "Приключения"
    };
    return genreArray.map(g => genreMap[g] || g).join(", ");
}

function getRecommendations() {
    if (watched.length === 0 && favorites.length === 0) return [];
    
    const watchedGenres = [];
    const favoriteGenres = [];
    
    watched.forEach(id => {
        const item = allItems.find(i => i.id === id);
        if (item && item.genre) item.genre.forEach(g => watchedGenres.push(g));
    });
    
    favorites.forEach(id => {
        const item = allItems.find(i => i.id === id);
        if (item && item.genre) item.genre.forEach(g => favoriteGenres.push(g));
    });
    
    const allGenres = [...watchedGenres, ...favoriteGenres];
    const genreCount = {};
    allGenres.forEach(g => { genreCount[g] = (genreCount[g] || 0) + 1; });
    
    const sortedGenres = Object.entries(genreCount).sort((a, b) => b[1] - a[1]);
    const topGenres = sortedGenres.slice(0, 2).map(g => g[0]);
    
    let recommendations = allItems.filter(item => 
        !watched.includes(item.id) && 
        item.genre && item.genre.some(g => topGenres.includes(g))
    );
    
    if (recommendations.length < 4) {
        const otherItems = allItems.filter(item => 
            !watched.includes(item.id) && 
            !recommendations.includes(item)
        );
        recommendations = [...recommendations, ...otherItems.slice(0, 8 - recommendations.length)];
    }
    
    return recommendations.slice(0, 8);
}

function renderMovieCard(item, showFav = true, showWatched = true) {
    const favClass = isFavorite(item.id) ? 'active' : '';
    const watchedClass = isWatched(item.id) ? 'active' : '';
    const rating = item.rating || '—';
    const age = item.age || item.ageRating || '—';
    
    const posterHtml = item.poster 
        ? `<img src="${item.poster}" alt="${item.title}">` 
        : `<div class="no-image">🎬<br>${item.title}</div>`;
    
    return `
        <div class="movie-card">
            <div class="movie-poster" onclick="showModalById(${item.id}, '${item.type}')">
                ${posterHtml}
                <div class="movie-badges">
                    <span class="rating-badge">⭐ ${rating}</span>
                    <span class="age-badge">${age}</span>
                </div>
            </div>
            <div class="movie-info">
                <div class="movie-title" onclick="showModalById(${item.id}, '${item.type}')">${item.title}</div>
                <div class="movie-year">${item.year} | ${getGenreDisplay(item.genre)}</div>
                <div class="movie-actions">
                    ${showFav ? `<button class="heart-btn ${favClass}" onclick="toggleFavorite(${item.id})">${isFavorite(item.id) ? '❤️' : '🤍'}</button>` : ''}
                    ${showWatched ? `<button class="watched-btn ${watchedClass}" onclick="toggleWatched(${item.id})">${isWatched(item.id) ? '✅' : '👁️'}</button>` : ''}
                </div>
            </div>
        </div>
    `;
}

function renderRecommended() {
    const recommendations = getRecommendations();
    const grid = document.getElementById('recommended-grid');
    if (recommendations.length === 0) {
        grid.innerHTML = '<p style="text-align: center; grid-column: 1/-1; color: #888;">Добавьте фильмы в "Просмотрено" или "Любимые", чтобы получить рекомендации</p>';
    } else {
        grid.innerHTML = recommendations.map(item => renderMovieCard(item, true, true)).join('');
    }
}

function showModalById(id, type) {
    const items = type === 'movie' ? moviesData : seriesData;
    const item = items.find(i => i.id == id);
    if (item) {
        document.getElementById('modalTitle').textContent = item.title;
        document.getElementById('modalPoster').innerHTML = item.poster ? `<img src="${item.poster}">` : `<div class="no-image">🎬 ${item.title}</div>`;
        document.getElementById('modalDetails').innerHTML = `
            <div class="info-grid">
                <div class="info-item"><span class="info-label">Год</span><span class="info-value">${item.year}</span></div>
                <div class="info-item"><span class="info-label">Страна</span><span class="info-value">${item.country || "—"}</span></div>
                <div class="info-item"><span class="info-label">Жанр</span><span class="info-value">${getGenreDisplay(item.genre)}</span></div>
                <div class="info-item"><span class="info-label">Слоган</span><span class="info-value">${item.tagline || "—"}</span></div>
                <div class="info-item"><span class="info-label">Режиссер</span><span class="info-value">${item.director || "—"}</span></div>
                <div class="info-item"><span class="info-label">Сценарий</span><span class="info-value">${item.writer || "—"}</span></div>
                <div class="info-item"><span class="info-label">Продюсер</span><span class="info-value">${item.producer || "—"}</span></div>
                <div class="info-item"><span class="info-label">Оператор</span><span class="info-value">${item.operator || "—"}</span></div>
                <div class="info-item"><span class="info-label">Композитор</span><span class="info-value">${item.composer || "—"}</span></div>
                <div class="info-item"><span class="info-label">Художник</span><span class="info-value">${item.artist || "—"}</span></div>
                <div class="info-item"><span class="info-label">Монтаж</span><span class="info-value">${item.editor || "—"}</span></div>
                <div class="info-item"><span class="info-label">Премьера</span><span class="info-value">${item.premiere || "—"}</span></div>
                <div class="info-item"><span class="info-label">Цифровой релиз</span><span class="info-value">${item.digital || "—"}</span></div>
                <div class="info-item"><span class="info-label">Возраст</span><span class="info-value">${item.ageRating || item.age || "—"}</span></div>
            </div>
        `;
        document.getElementById('modalCast').innerHTML = item.cast ? `
            <div class="cast-title">В ГЛАВНЫХ РОЛЯХ</div>
            <div class="cast-list">
                ${item.cast.map(actor => `<div class="cast-item">${actor}</div>`).join('')}
            </div>
        ` : '';
        document.getElementById('modalDescription').textContent = item.description;
        document.getElementById('modalOverlay').classList.add('show');
        document.body.style.overflow = 'hidden';
    }
}

function filterByGenre(items, genre) {
    if (genre === 'all') return items;
    return items.filter(item => item.genre && item.genre.includes(genre));
}

function searchItems(items, query) {
    if (!query) return items;
    return items.filter(item => item.title.toLowerCase().includes(query.toLowerCase()));
}

let currentTab = 'movies';
let currentMovieGenre = 'all';
let currentSeriesGenre = 'all';
let currentSearchQuery = '';

function renderMovies() {
    let filtered = filterByGenre(moviesData, currentMovieGenre);
    filtered = searchItems(filtered, currentSearchQuery);
    document.getElementById('movies-grid').innerHTML = filtered.map(m => renderMovieCard(m)).join('');
}

function renderSeries() {
    let filtered = filterByGenre(seriesData, currentSeriesGenre);
    filtered = searchItems(filtered, currentSearchQuery);
    document.getElementById('series-grid').innerHTML = filtered.map(s => renderMovieCard(s)).join('');
}

function renderFavorites() {
    let favoriteItems = allItems.filter(item => isFavorite(item.id));
    favoriteItems = searchItems(favoriteItems, currentSearchQuery);
    const grid = document.getElementById('favorites-grid');
    if (favoriteItems.length === 0) {
        grid.innerHTML = '<p style="text-align: center; grid-column: 1/-1; color: #888;">Добавьте фильмы в любимые, нажав на сердечко ❤️</p>';
    } else {
        grid.innerHTML = favoriteItems.map(item => renderMovieCard(item, false, true)).join('');
    }
}

function renderWatched() {
    let watchedItems = allItems.filter(item => isWatched(item.id));
    watchedItems = searchItems(watchedItems, currentSearchQuery);
    const grid = document.getElementById('watched-grid');
    if (watchedItems.length === 0) {
        grid.innerHTML = '<p style="text-align: center; grid-column: 1/-1; color: #888;">Отмечайте просмотренные фильмы галочкой ✅</p>';
    } else {
        grid.innerHTML = watchedItems.map(item => renderMovieCard(item, true, false)).join('');
    }
}

function renderCurrentView() {
    if (currentTab === 'movies') renderMovies();
    else if (currentTab === 'series') renderSeries();
    else if (currentTab === 'favorites') renderFavorites();
    else if (currentTab === 'watched') renderWatched();
}

function toggleGenres(tabId, show) {
    const wrapper = document.getElementById(`${tabId}-genres-wrapper`);
    if (wrapper) {
        if (show) wrapper.classList.add('show');
        else wrapper.classList.remove('show');
    }
}

function switchTab(tabId) {
    currentTab = tabId;
    document.querySelectorAll('.tab-pane').forEach(pane => pane.classList.remove('active-pane'));
    document.getElementById(tabId).classList.add('active-pane');
    document.querySelectorAll('.tab-btn').forEach(btn => {
        btn.classList.remove('active');
        if (btn.dataset.tab === tabId) btn.classList.add('active');
    });
    
    if (tabId === 'movies') { toggleGenres('movies', true); toggleGenres('series', false); renderMovies(); }
    else if (tabId === 'series') { toggleGenres('movies', false); toggleGenres('series', true); renderSeries(); }
    else if (tabId === 'recommended') { toggleGenres('movies', false); toggleGenres('series', false); renderRecommended(); }
    else if (tabId === 'favorites') { toggleGenres('movies', false); toggleGenres('series', false); renderFavorites(); }
    else if (tabId === 'watched') { toggleGenres('movies', false); toggleGenres('series', false); renderWatched(); }
    else { toggleGenres('movies', false); toggleGenres('series', false); }
}

function setupGenreListeners() {
    document.querySelectorAll('#movies-genres .genre-btn').forEach(btn => {
        btn.addEventListener('click', () => {
            document.querySelectorAll('#movies-genres .genre-btn').forEach(b => b.classList.remove('active-genre'));
            btn.classList.add('active-genre');
            currentMovieGenre = btn.dataset.genre;
            renderMovies();
        });
    });
    document.querySelectorAll('#series-genres .genre-btn').forEach(btn => {
        btn.addEventListener('click', () => {
            document.querySelectorAll('#series-genres .genre-btn').forEach(b => b.classList.remove('active-genre'));
            btn.classList.add('active-genre');
            currentSeriesGenre = btn.dataset.genre;
            renderSeries();
        });
    });
}

// ПОИСК
const searchInput = document.getElementById('searchInput');
if (searchInput) {
    searchInput.addEventListener('input', (e) => {
        currentSearchQuery = e.target.value;
        if (currentTab === 'movies') renderMovies();
        else if (currentTab === 'series') renderSeries();
        else if (currentTab === 'favorites') renderFavorites();
        else if (currentTab === 'watched') renderWatched();
    });
}

// МОДАЛЬНОЕ ОКНО
const modalCloseBtn = document.getElementById('modalCloseBtn');
const modalOverlay = document.getElementById('modalOverlay');

if (modalCloseBtn) {
    modalCloseBtn.addEventListener('click', () => {
        modalOverlay.classList.remove('show');
        document.body.style.overflow = '';
    });
}
if (modalOverlay) {
    modalOverlay.addEventListener('click', (e) => {
        if (e.target === modalOverlay) {
            modalOverlay.classList.remove('show');
            document.body.style.overflow = '';
        }
    });
}

// ИНИЦИАЛИЗАЦИЯ
document.querySelectorAll('.tab-btn').forEach(btn => {
    if (btn.dataset && btn.dataset.tab) {
        btn.addEventListener('click', () => switchTab(btn.dataset.tab));
    }
});
setupGenreListeners();
switchTab('movies');